-- Generated from verified live MariaDB metadata, not the older seed schema.
-- Run in a NEW empty PostgreSQL database. Source timestamps were exported in UTC.
SET TIME ZONE 'UTC';
CREATE COLLATION snacktime_ci (provider = icu, locale = 'und-u-ks-level1', deterministic = false);
CREATE EXTENSION IF NOT EXISTS unaccent;

CREATE TABLE "categories" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(60) COLLATE snacktime_ci NOT NULL,
  "slug" varchar(60) COLLATE snacktime_ci NOT NULL,
  "icon" varchar(10) COLLATE snacktime_ci DEFAULT '',
  "display_order" integer DEFAULT 0,
  "active" smallint DEFAULT 1 NOT NULL CHECK ("active" IN (0,1)),
  PRIMARY KEY ("id")
);

CREATE TABLE "discounts" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(60) COLLATE snacktime_ci NOT NULL,
  "type" varchar(30) COLLATE snacktime_ci DEFAULT 'fixed' NOT NULL CHECK ("type" IN ('percent','fixed')),
  "value" numeric(10,2) DEFAULT 0.00 NOT NULL,
  "active" smallint DEFAULT 1 NOT NULL CHECK ("active" IN (0,1)),
  PRIMARY KEY ("id")
);

CREATE TABLE "ingredients" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(100) COLLATE snacktime_ci NOT NULL,
  "unit" varchar(20) COLLATE snacktime_ci DEFAULT 'pcs' NOT NULL,
  "current_stock" numeric(12,2) DEFAULT 0.00 NOT NULL,
  "min_stock" numeric(12,2) DEFAULT 0.00 NOT NULL,
  "cost_per_unit" numeric(10,2) DEFAULT 0.00,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "inventory_transactions" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "ingredient_id" integer NOT NULL,
  "type" varchar(30) COLLATE snacktime_ci NOT NULL CHECK ("type" IN ('add','deduct','adjust')),
  "quantity" numeric(12,2) NOT NULL,
  "resulting_stock" numeric(12,2) NOT NULL,
  "reason" varchar(255) COLLATE snacktime_ci DEFAULT '',
  "reference_order_id" integer DEFAULT NULL,
  "user_id" integer DEFAULT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "options" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "option_group_id" integer NOT NULL,
  "name" varchar(60) COLLATE snacktime_ci NOT NULL,
  "price_modifier" numeric(10,2) DEFAULT 0.00 NOT NULL,
  "display_order" integer DEFAULT 0,
  PRIMARY KEY ("id")
);

CREATE TABLE "option_groups" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "product_id" integer NOT NULL,
  "name" varchar(60) COLLATE snacktime_ci NOT NULL,
  "selection_type" varchar(30) COLLATE snacktime_ci DEFAULT 'single' NOT NULL CHECK ("selection_type" IN ('single','multi')),
  "is_required" smallint DEFAULT 1 NOT NULL CHECK ("is_required" IN (0,1)),
  "display_order" integer DEFAULT 0,
  PRIMARY KEY ("id")
);

CREATE TABLE "option_ingredients" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "option_id" integer NOT NULL,
  "ingredient_id" integer NOT NULL,
  "quantity_required" numeric(12,2) NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "orders" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "order_number" varchar(30) COLLATE snacktime_ci NOT NULL,
  "user_id" integer NOT NULL,
  "subtotal" numeric(10,2) NOT NULL,
  "discount_id" integer DEFAULT NULL,
  "discount_amount" numeric(10,2) DEFAULT 0.00 NOT NULL,
  "total" numeric(10,2) NOT NULL,
  "payment_method" varchar(30) COLLATE snacktime_ci NOT NULL CHECK ("payment_method" IN ('cash','gcash','other')),
  "cash_received" numeric(10,2) DEFAULT NULL,
  "change_amount" numeric(10,2) DEFAULT NULL,
  "status" varchar(30) COLLATE snacktime_ci DEFAULT 'completed' NOT NULL CHECK ("status" IN ('completed','voided')),
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "order_items" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "order_id" integer NOT NULL,
  "product_id" integer NOT NULL,
  "product_name" varchar(120) COLLATE snacktime_ci NOT NULL,
  "unit_price" numeric(10,2) NOT NULL,
  "quantity" integer NOT NULL,
  "subtotal" numeric(10,2) NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "order_item_options" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "order_item_id" integer NOT NULL,
  "option_group_name" varchar(60) COLLATE snacktime_ci NOT NULL,
  "option_name" varchar(60) COLLATE snacktime_ci NOT NULL,
  "price_modifier" numeric(10,2) DEFAULT 0.00 NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "products" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "category_id" integer NOT NULL,
  "name" varchar(120) COLLATE snacktime_ci NOT NULL,
  "description" varchar(255) COLLATE snacktime_ci DEFAULT '',
  "price" numeric(10,2) NOT NULL,
  "image" varchar(255) COLLATE snacktime_ci DEFAULT NULL,
  "available" smallint DEFAULT 1 NOT NULL CHECK ("available" IN (0,1)),
  "track_stock" smallint DEFAULT 0 NOT NULL CHECK ("track_stock" IN (0,1)),
  "stock" integer DEFAULT NULL,
  "low_stock_threshold" integer DEFAULT 10,
  "sku" varchar(40) COLLATE snacktime_ci DEFAULT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "deleted_at" timestamptz DEFAULT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "product_ingredients" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "product_id" integer NOT NULL,
  "ingredient_id" integer NOT NULL,
  "quantity_required" numeric(12,2) NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "roles" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(30) COLLATE snacktime_ci NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "settings" (
  "setting_key" varchar(60) COLLATE snacktime_ci NOT NULL,
  "setting_value" varchar(500) COLLATE snacktime_ci DEFAULT '' NOT NULL,
  PRIMARY KEY ("setting_key")
);

CREATE TABLE "users" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "role_id" integer NOT NULL,
  "full_name" varchar(100) COLLATE snacktime_ci NOT NULL,
  "username" varchar(50) COLLATE snacktime_ci NOT NULL,
  "email" varchar(120) COLLATE snacktime_ci DEFAULT NULL,
  "password_hash" varchar(255) COLLATE snacktime_ci NOT NULL,
  "active" smallint DEFAULT 1 NOT NULL CHECK ("active" IN (0,1)),
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY ("id")
