CREATE FUNCTION touch_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.updated_at IS NOT DISTINCT FROM OLD.updated_at AND NEW IS DISTINCT FROM OLD THEN NEW.updated_at = CURRENT_TIMESTAMP; END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER "ingredients_updated_at" BEFORE UPDATE ON "ingredients" FOR EACH ROW EXECUTE FUNCTION touch_updated_at();
